// The single source of truth for timing. Generated by audio/make_vo.py from
// src/data/script.json: scene starts/lengths, voiceover files and per-word frames
// (absolute composition frames, 60 fps, cuts on the 120 BPM beat grid).
import en from "./data/timeline.en.json";

export type Lang = "en";
export type SceneId = "cold-open" | "problem" | "reveal" | "turn" | "specs" | "finder" | "brands" | "endcard";

export interface Word {
  text: string;
  start: number;
  end: number;
}
export interface SceneTiming {
  id: SceneId;
  start: number;
  duration: number;
  vo: { file: string; text: string; at: number; durationInFrames: number; speechEnd: number; words: Word[] };
}
export interface Timeline {
  lang: Lang;
  fps: number;
  bpm: number;
  barFrames: number;
  beatFrames: number;
  overlapFrames: number;
  durationInFrames: number;
  scenes: SceneTiming[];
}

export const TIMELINES: Record<Lang, Timeline> = { en: en as Timeline };

export const scene = (t: Timeline, id: SceneId): SceneTiming => {
  const s = t.scenes.find((x) => x.id === id);
  if (!s) throw new Error(`No scene ${id}`);
  return s;
};

/**
 * Frame (relative to the scene's own start) at which the n-th occurrence of a
 * word is spoken, matched case-insensitively without punctuation. Use it to sync
 * clicks and reveals to the voice. Falls back to `fallback` if not found.
 */
export const wordAt = (s: SceneTiming, word: string, fallback: number, nth = 0, edge: "start" | "end" = "start"): number => {
  const norm = (x: string) => x.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");
  const hits = s.vo.words.filter((w) => norm(w.text) === norm(word));
  const w = hits[nth];
  return w ? w[edge] - s.start : fallback;
};
